CREATE TABLE public.receivables (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), establishment_id uuid NOT NULL REFERENCES public.profiles(id), client_id uuid NOT NULL REFERENCES public.clients(id), service_id uuid REFERENCES public.services(id), professional_id uuid REFERENCES public.professionals(id), comanda_id uuid REFERENCES public.comandas(id), description text NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount>0), received_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(received_amount>=0 AND received_amount<=amount), initial_paid numeric(14,2) NOT NULL DEFAULT 0, entry_date date NOT NULL DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo')::date, due_date date NOT NULL, expected_method text NOT NULL DEFAULT 'Pix', notes text, canceled_at timestamptz, cancellation_reason text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), request_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.receivables TO authenticated;
GRANT ALL ON public.receivables TO service_role;
ALTER TABLE public.receivables ENABLE ROW LEVEL SECURITY;
CREATE POLICY receivables_manager_read ON public.receivables FOR SELECT TO authenticated USING(public.is_establishment_admin(establishment_id,auth.uid()));
CREATE UNIQUE INDEX receivable_comanda_unique ON public.receivables(comanda_id) WHERE comanda_id IS NOT NULL;
CREATE INDEX receivables_tenant_due ON public.receivables(establishment_id,due_date);
CREATE INDEX receivables_client ON public.receivables(establishment_id,client_id);
CREATE TABLE public.receivable_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receivable_id uuid NOT NULL REFERENCES public.receivables(id), establishment_id uuid NOT NULL REFERENCES public.profiles(id), amount numeric(14,2) NOT NULL CHECK(amount>0), payment_date date NOT NULL, payment_method text NOT NULL, notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), request_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.receivable_payments TO authenticated;
GRANT ALL ON public.receivable_payments TO service_role;
ALTER TABLE public.receivable_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY receivable_payments_manager_read ON public.receivable_payments FOR SELECT TO authenticated USING(public.is_establishment_admin(establishment_id,auth.uid()));
CREATE INDEX receivable_payments_period ON public.receivable_payments(establishment_id,payment_date);
CREATE TABLE public.receivable_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receivable_id uuid NOT NULL REFERENCES public.receivables(id), establishment_id uuid NOT NULL REFERENCES public.profiles(id), operation text NOT NULL, old_values jsonb, new_values jsonb, user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.receivable_audit_logs TO authenticated;
GRANT ALL ON public.receivable_audit_logs TO service_role;
ALTER TABLE public.receivable_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY receivable_audit_manager_read ON public.receivable_audit_logs FOR SELECT TO authenticated USING(public.is_establishment_admin(establishment_id,auth.uid()));
ALTER TABLE public.sales ADD COLUMN receivable_id uuid REFERENCES public.receivables(id);
ALTER TABLE public.sales ADD COLUMN deferred_amount numeric(14,2) NOT NULL DEFAULT 0;
ALTER TABLE public.sales ADD CONSTRAINT sales_deferred_amount_valid CHECK(deferred_amount>=0 AND deferred_amount<=amount) NOT VALID;
CREATE INDEX sales_receivable ON public.sales(receivable_id) WHERE receivable_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.receivable_status(p_amount numeric,p_received numeric,p_due date,p_canceled timestamptz) RETURNS text LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN p_canceled IS NOT NULL THEN 'canceled' WHEN p_received>=p_amount THEN 'received' WHEN p_due<(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN CASE WHEN p_received>0 THEN 'partial_overdue' ELSE 'overdue' END WHEN p_received>0 THEN 'partial' ELSE 'pending' END $$;
REVOKE ALL ON FUNCTION public.receivable_status(numeric,numeric,date,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.receivable_status(numeric,numeric,date,timestamptz) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.audit_receivable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN INSERT INTO public.receivable_audit_logs(receivable_id,establishment_id,operation,old_values,new_values,user_id) VALUES(NEW.id,NEW.establishment_id,CASE WHEN TG_OP='INSERT' THEN 'create' WHEN NEW.canceled_at IS DISTINCT FROM OLD.canceled_at THEN 'cancel' WHEN NEW.received_amount IS DISTINCT FROM OLD.received_amount THEN 'receive' ELSE 'edit' END,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) END,to_jsonb(NEW),auth.uid()); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_receivable() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_receivable AFTER INSERT OR UPDATE ON public.receivables FOR EACH ROW EXECUTE FUNCTION public.audit_receivable();
CREATE OR REPLACE FUNCTION public.create_receivable(p_establishment uuid,p_data jsonb,p_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_id uuid; v_client uuid; v_service uuid; v_prof uuid; BEGIN IF auth.uid() IS NULL OR NOT public.is_establishment_admin(p_establishment,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para contas a receber'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('receivable:'||p_request::text,0)); SELECT id INTO v_id FROM public.receivables WHERE request_id=p_request AND establishment_id=p_establishment; IF FOUND THEN RETURN v_id; END IF; v_client=(p_data->>'client_id')::uuid; v_service=nullif(p_data->>'service_id','')::uuid; v_prof=nullif(p_data->>'professional_id','')::uuid; IF NOT EXISTS(SELECT 1 FROM public.clients WHERE id=v_client AND establishment_id=p_establishment) THEN RAISE EXCEPTION 'Cliente inválido'; END IF; IF v_service IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.services WHERE id=v_service AND establishment_id=p_establishment) THEN RAISE EXCEPTION 'Serviço inválido'; END IF; IF v_prof IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.professionals WHERE id=v_prof AND establishment_id=p_establishment) THEN RAISE EXCEPTION 'Profissional inválido'; END IF; IF coalesce(trim(p_data->>'description'),'')='' THEN RAISE EXCEPTION 'Informe a descrição'; END IF; INSERT INTO public.receivables(establishment_id,client_id,service_id,professional_id,description,amount,entry_date,due_date,expected_method,notes,created_by,request_id) VALUES(p_establishment,v_client,v_service,v_prof,p_data->>'description',(p_data->>'amount')::numeric,(p_data->>'entry_date')::date,(p_data->>'due_date')::date,coalesce(p_data->>'expected_method','Pix'),p_data->>'notes',auth.uid(),p_request) RETURNING id INTO v_id; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.receive_receivable(p_id uuid,p_amount numeric,p_date date,p_method text,p_notes text,p_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r public.receivables%rowtype; v_id uuid; BEGIN SELECT * INTO r FROM public.receivables WHERE id=p_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR NOT public.is_establishment_admin(r.establishment_id,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para contas a receber'; END IF; SELECT id INTO v_id FROM public.receivable_payments WHERE request_id=p_request AND receivable_id=p_id; IF FOUND THEN RETURN v_id; END IF; IF r.canceled_at IS NOT NULL THEN RAISE EXCEPTION 'Conta cancelada'; END IF; IF p_amount IS NULL OR p_amount<=0 OR p_amount<>round(p_amount,2) OR p_amount>r.amount-r.received_amount THEN RAISE EXCEPTION 'O recebimento deve ser positivo e não pode ultrapassar o saldo devedor'; END IF; IF p_date IS NULL OR p_date>(now() AT TIME ZONE 'America/Sao_Paulo')::date OR p_date<r.entry_date THEN RAISE EXCEPTION 'Data de recebimento inválida'; END IF; IF coalesce(trim(p_method),'')='' THEN RAISE EXCEPTION 'Informe a forma de pagamento'; END IF; INSERT INTO public.receivable_payments(receivable_id,establishment_id,amount,payment_date,payment_method,notes,created_by,request_id) VALUES(p_id,r.establishment_id,p_amount,p_date,p_method,p_notes,auth.uid(),p_request) RETURNING id INTO v_id; UPDATE public.receivables SET received_amount=received_amount+p_amount,updated_at=now() WHERE id=p_id; INSERT INTO public.cash_flow_entries(establishment_id,entry_type,category,description,amount,payment_method,status,entry_date,source,source_id,notes) VALUES(r.establishment_id,'income','Contas a receber',r.description,p_amount,p_method,'confirmed',(p_date::timestamp AT TIME ZONE 'America/Sao_Paulo'),'manual',v_id,'Recebimento da conta '||p_id::text); RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.update_receivable(p_id uuid,p_data jsonb,p_cancel boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r public.receivables%rowtype; v_amount numeric; BEGIN SELECT * INTO r FROM public.receivables WHERE id=p_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR NOT public.is_establishment_admin(r.establishment_id,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para contas a receber'; END IF; IF r.canceled_at IS NOT NULL THEN RAISE EXCEPTION 'Conta cancelada não pode ser alterada'; END IF; IF p_cancel THEN IF coalesce(trim(p_data->>'reason'),'')='' THEN RAISE EXCEPTION 'Informe o motivo do cancelamento'; END IF; UPDATE public.receivables SET canceled_at=now(),cancellation_reason=p_data->>'reason',updated_at=now() WHERE id=p_id; RETURN; END IF; v_amount=coalesce((p_data->>'amount')::numeric,r.amount); IF r.comanda_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.sales WHERE receivable_id=p_id) THEN IF v_amount<>r.amount THEN RAISE EXCEPTION 'Valor de conta vinculada a venda não pode ser alterado'; END IF; END IF; IF v_amount<=0 OR v_amount<r.received_amount OR coalesce(trim(p_data->>'description'),'')='' THEN RAISE EXCEPTION 'Descrição ou valor inválido'; END IF; UPDATE public.receivables SET amount=v_amount,description=p_data->>'description',due_date=(p_data->>'due_date')::date,expected_method=coalesce(p_data->>'expected_method',r.expected_method),notes=p_data->>'notes',updated_at=now() WHERE id=p_id; END $$;
CREATE OR REPLACE FUNCTION public.guard_deferred_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.receivable_id IS NULL AND NEW.deferred_amount<>0 THEN RAISE EXCEPTION 'Venda a prazo exige conta a receber'; END IF; IF NEW.receivable_id IS NOT NULL AND (coalesce(current_setting('app.receivable_checkout',true),'')<>'on' OR NOT EXISTS(SELECT 1 FROM public.receivables r WHERE r.id=NEW.receivable_id AND r.establishment_id=NEW.establishment_id AND r.client_id=NEW.client_id)) THEN RAISE EXCEPTION 'Use o fechamento protegido para venda a prazo'; END IF; ELSIF OLD.receivable_id IS NOT NULL THEN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Venda vinculada a conta a receber possui histórico protegido'; END IF; IF (NEW.amount,NEW.gross_amount,NEW.paid_now,NEW.credit_used,NEW.deferred_amount,NEW.deleted_at,NEW.receivable_id,NEW.client_id,NEW.service_id,NEW.professional_id,NEW.sale_date,NEW.payment_method,NEW.fee_amount,NEW.net_amount) IS DISTINCT FROM (OLD.amount,OLD.gross_amount,OLD.paid_now,OLD.credit_used,OLD.deferred_amount,OLD.deleted_at,OLD.receivable_id,OLD.client_id,OLD.service_id,OLD.professional_id,OLD.sale_date,OLD.payment_method,OLD.fee_amount,OLD.net_amount) THEN RAISE EXCEPTION 'Venda a prazo possui histórico protegido; gerencie a conta a receber'; END IF; ELSIF TG_OP='UPDATE' AND (NEW.receivable_id IS NOT NULL OR NEW.deferred_amount<>0) THEN RAISE EXCEPTION 'Venda existente não pode ser convertida em conta a receber'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_deferred_sale() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_deferred_sale BEFORE INSERT OR UPDATE OR DELETE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.guard_deferred_sale();
CREATE OR REPLACE FUNCTION public.checkout_receivable(p_establishment uuid,p_client uuid,p_items jsonb,p_total numeric,p_paid numeric,p_credit numeric,p_due date,p_method text,p_request uuid,p_comanda uuid DEFAULT NULL,p_professionals jsonb DEFAULT '[]',p_notes text DEFAULT NULL,p_machine uuid DEFAULT NULL,p_installments integer DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_id uuid; c public.comandas%rowtype; it jsonb; svc public.services%rowtype; prof public.professionals%rowtype; v_prof uuid; v_sale uuid; v_count int; v_index int=0; v_base numeric; v_subtotal numeric=0; v_gross numeric; v_cash numeric; v_credit numeric; v_debt numeric; v_fee numeric; v_rate numeric=0; sum_gross numeric=0; sum_cash numeric=0; sum_credit numeric=0; v_appointment uuid; v_prof_ids uuid[];
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_establishment_admin(p_establishment,auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para venda a prazo'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('receivable:'||p_request::text,0));
 SELECT id INTO v_id FROM public.receivables WHERE request_id=p_request AND establishment_id=p_establishment; IF FOUND THEN RETURN v_id; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clients WHERE id=p_client AND establishment_id=p_establishment) THEN RAISE EXCEPTION 'Cliente inválido'; END IF;
 IF p_due IS NULL OR p_total IS NULL OR p_paid IS NULL OR p_credit IS NULL OR p_total<=0 OR p_paid<0 OR p_credit<0 OR p_paid+p_credit>=p_total OR p_total<>round(p_total,2) OR p_paid<>round(p_paid,2) OR p_credit<>round(p_credit,2) THEN RAISE EXCEPTION 'Informe total, entrada e vencimento válidos'; END IF;
 IF p_comanda IS NOT NULL THEN
 SELECT * INTO c FROM public.comandas WHERE id=p_comanda AND establishment_id=p_establishment FOR UPDATE;
 IF NOT FOUND OR c.client_id<>p_client OR c.status NOT IN('open','awaiting_payment') THEN RAISE EXCEPTION 'Comanda inválida ou encerrada'; END IF;
 IF EXISTS(SELECT 1 FROM public.receivables WHERE comanda_id=p_comanda) THEN RAISE EXCEPTION 'Comanda já possui conta a receber'; END IF;
 v_appointment=c.appointment_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('service_id',service_id,'professional_id',professional_id,'total',total,'qty',qty,'commission_percentage',commission_percentage)),'[]') INTO p_items FROM public.comanda_items WHERE comanda_id=p_comanda AND establishment_id=p_establishment AND payment_source='cash';
 SELECT sum(total) INTO v_subtotal FROM public.comanda_items WHERE comanda_id=p_comanda AND establishment_id=p_establishment;
 IF round(greatest(0,coalesce(v_subtotal,0)-c.discount),2)<>p_total THEN RAISE EXCEPTION 'O total da comanda mudou; atualize antes de finalizar'; END IF;
 IF EXISTS(SELECT 1 FROM public.comanda_items WHERE comanda_id=p_comanda AND payment_source<>'cash') THEN RAISE EXCEPTION 'Itens de pacote ou assinatura devem ser finalizados separadamente'; END IF;
 SELECT array_agg(professional_id) INTO v_prof_ids FROM public.appointment_professionals WHERE appointment_id=v_appointment;
 ELSE SELECT array_agg(DISTINCT (x->>'professional_id')::uuid) INTO v_prof_ids FROM jsonb_array_elements(p_professionals) x; END IF;
 IF jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Adicione itens'; END IF;
 SELECT sum((x->>'total')::numeric),sum((x->>'qty')::int) INTO v_subtotal,v_count FROM jsonb_array_elements(p_items) x;
 IF v_subtotal<=0 OR v_count<=0 OR v_count>500 THEN RAISE EXCEPTION 'Itens inválidos'; END IF;
 IF p_machine IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM public.card_machines WHERE id=p_machine AND establishment_id=p_establishment AND active) THEN RAISE EXCEPTION 'Maquininha inválida'; END IF;
 SELECT coalesce(fee_percentage,0) INTO v_rate FROM public.card_machine_fees WHERE card_machine_id=p_machine AND payment_type=CASE WHEN p_method='Débito' THEN 'debit' WHEN p_installments>1 THEN 'credit_installment' ELSE 'credit' END AND (p_installments IS NULL OR installments=p_installments) LIMIT 1; v_rate=coalesce(v_rate,0); END IF;
 INSERT INTO public.receivables(establishment_id,client_id,comanda_id,description,amount,initial_paid,due_date,expected_method,notes,created_by,request_id) VALUES(p_establishment,p_client,p_comanda,CASE WHEN p_comanda IS NULL THEN 'Venda a prazo' ELSE 'Comanda a prazo' END,p_total-p_paid-p_credit,p_paid+p_credit,p_due,p_method,p_notes,auth.uid(),p_request) RETURNING id INTO v_id;
 PERFORM set_config('app.receivable_checkout','on',true);
 FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
 SELECT * INTO svc FROM public.services WHERE id=(it->>'service_id')::uuid AND establishment_id=p_establishment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Serviço inválido'; END IF;
 v_prof=coalesce(nullif(it->>'professional_id','')::uuid,v_prof_ids[1]);
 IF NOT EXISTS(SELECT 1 FROM public.professionals WHERE id=v_prof AND establishment_id=p_establishment) THEN RAISE EXCEPTION 'Selecione o profissional de cada item'; END IF;
 IF (it->>'qty')::int<=0 OR (it->>'total')::numeric<0 THEN RAISE EXCEPTION 'Quantidade ou valor inválido'; END IF;
 IF svc.kind='product' AND svc.stock_quantity<(it->>'qty')::int THEN RAISE EXCEPTION 'Estoque insuficiente'; END IF;
 FOR j IN 1..(it->>'qty')::int LOOP
 v_index=v_index+1;
 v_gross=CASE WHEN v_index=v_count THEN p_total-sum_gross ELSE round((it->>'total')::numeric/(it->>'qty')::int/v_subtotal*p_total,2) END;
 v_cash=CASE WHEN v_index=v_count THEN p_paid-sum_cash ELSE round(v_gross/p_total*p_paid,2) END;
 v_credit=CASE WHEN v_index=v_count THEN p_credit-sum_credit ELSE round(v_gross/p_total*p_credit,2) END;
 v_debt=v_gross-v_cash-v_credit; v_fee=round(v_cash*v_rate/100,2);
 sum_gross=sum_gross+v_gross; sum_cash=sum_cash+v_cash; sum_credit=sum_credit+v_credit;
 INSERT INTO public.sales(establishment_id,client_id,service_id,professional_id,appointment_id,amount,gross_amount,paid_now,credit_used,deferred_amount,receivable_id,fee_amount,net_amount,payment_method,sale_date,created_by_user_id,card_machine_id,installments,notes) VALUES(p_establishment,p_client,svc.id,v_prof,v_appointment,v_gross,v_gross,v_cash,v_credit,v_debt,v_id,v_fee,v_cash-v_fee,p_method,now(),auth.uid(),p_machine,p_installments,p_notes) RETURNING id INTO v_sale;
 IF v_credit>0 THEN PERFORM public.use_client_credit(p_client,v_credit,'sale_usage','Uso de crédito em venda a prazo','sale',v_sale); END IF;
 FOR prof IN SELECT * FROM public.professionals WHERE establishment_id=p_establishment AND id=ANY(coalesce(v_prof_ids,ARRAY[v_prof])) LOOP
 IF prof.commission_type<>'fixed_daily' THEN v_base=v_gross/cardinality(coalesce(v_prof_ids,ARRAY[v_prof])); INSERT INTO public.sale_professionals(establishment_id,sale_id,professional_id,role,commission_percentage,commission_amount) VALUES(p_establishment,v_sale,prof.id,'solo',CASE WHEN prof.commission_type='custom_percentage' THEN prof.custom_percentage ELSE svc.commission_solo END,round(v_base*(CASE WHEN prof.commission_type='custom_percentage' THEN prof.custom_percentage ELSE svc.commission_solo END)/100,2)); END IF; END LOOP;
 END LOOP; END LOOP;
 IF EXISTS(SELECT 1 FROM unnest(v_prof_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.professionals WHERE id=x AND establishment_id=p_establishment)) THEN RAISE EXCEPTION 'Profissional inválido'; END IF;
 IF p_comanda IS NOT NULL THEN UPDATE public.comandas SET status='paid',closed_at=now() WHERE id=p_comanda; END IF;
 IF v_appointment IS NOT NULL THEN UPDATE public.appointments SET status='completed' WHERE id=v_appointment; END IF; RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.create_receivable(uuid,jsonb,uuid),public.receive_receivable(uuid,numeric,date,text,text,uuid),public.update_receivable(uuid,jsonb,boolean),public.checkout_receivable(uuid,uuid,jsonb,numeric,numeric,numeric,date,text,uuid,uuid,jsonb,text,uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_receivable(uuid,jsonb,uuid),public.receive_receivable(uuid,numeric,date,text,text,uuid),public.update_receivable(uuid,jsonb,boolean),public.checkout_receivable(uuid,uuid,jsonb,numeric,numeric,numeric,date,text,uuid,uuid,jsonb,text,uuid,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.sync_sale_to_cash_flow() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE svc_name text; v_fee numeric; v_gross numeric; v_credit numeric; v_cash_income numeric; BEGIN IF TG_OP='DELETE' THEN DELETE FROM public.cash_flow_entries WHERE source IN('sale','sale_fee') AND source_id=OLD.id; RETURN OLD; END IF; IF TG_OP='UPDATE' AND NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN DELETE FROM public.cash_flow_entries WHERE source IN('sale','sale_fee') AND source_id=NEW.id; RETURN NEW; END IF; IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF; SELECT name INTO svc_name FROM public.services WHERE id=NEW.service_id; v_fee=coalesce(NEW.fee_amount,0); v_gross=coalesce(NEW.gross_amount,NEW.amount); v_credit=coalesce(NEW.credit_used,0); v_cash_income=greatest(coalesce(NEW.paid_now,v_gross-v_credit),0); IF TG_OP='UPDATE' THEN DELETE FROM public.cash_flow_entries WHERE source IN('sale','sale_fee') AND source_id=NEW.id; END IF; IF v_cash_income>0 THEN INSERT INTO public.cash_flow_entries(establishment_id,entry_type,category,description,amount,payment_method,status,entry_date,source,source_id,notes) VALUES(NEW.establishment_id,'income','Serviço',coalesce(svc_name,'Venda'),v_cash_income,NEW.payment_method,'confirmed',NEW.sale_date,'sale',NEW.id,NEW.notes); END IF; IF v_fee>0 THEN INSERT INTO public.cash_flow_entries(establishment_id,entry_type,category,description,amount,payment_method,status,entry_date,source,source_id,notes) VALUES(NEW.establishment_id,'expense','Taxa de cartão','Taxa '||coalesce(NEW.payment_method,'cartão'),v_fee,NEW.payment_method,'confirmed',NEW.sale_date,'sale_fee',NEW.id,'Taxa automática da venda'); END IF; RETURN NEW; END $$;